int c11(int order, int *expected) {
    __c11_atomic_init(&counter, 0);
    __c11_atomic_store(&counter, 1, 0);
    int a = __c11_atomic_load(&counter, 1);
    a += __c11_atomic_load(&counter, 2);
    __c11_atomic_store(&counter, 2, 3);
    a += __c11_atomic_exchange(&counter, 3, 4);
    a += __c11_atomic_fetch_add(&counter, 1, 5);
    a += __c11_atomic_fetch_sub(&counter, 1, 0);
    a += __c11_atomic_fetch_and(&counter, 6, 0);
    a += __c11_atomic_fetch_or(&counter, 6, 0);
    a += __c11_atomic_fetch_xor(&counter, 6, 0);
    a += __c11_atomic_fetch_nand(&counter, 6, 0);
    a += __c11_atomic_fetch_min(&counter, 6, 0);
    a += __c11_atomic_fetch_max(&counter, 6, 0);
    a += __c11_atomic_compare_exchange_strong(&counter, expected, 7, 4, 2);
    a += __c11_atomic_compare_exchange_weak(&counter, expected, 7, 5, 0);
    __c11_atomic_fetch_add(&cursor, 1, 5);
    __c11_atomic_fetch_sub(&cursor, 1, 5);
    __c11_atomic_thread_fence(2);
    __c11_atomic_signal_fence(3);
    a += __c11_atomic_load(&counter, order);
    __c11_atomic_thread_fence(order);
    return a;
}

int gnu(int order, int *expected, int *desired) {
    __atomic_store_n(&plain, 1, 0);
    int a = __atomic_load_n(&plain, 1);
    int r;
    __atomic_load(&plain, &r, 2);
    __atomic_store(&plain, &r, 3);
    a += __atomic_exchange_n(&plain, 3, 4);
    __atomic_exchange(&plain, desired, &r, 5);
    a += __atomic_fetch_add(&plain, 1, 0);
    a += __atomic_add_fetch(&plain, 1, 0);
    a += __atomic_sub_fetch(&plain, 1, 0);
    a += __atomic_and_fetch(&plain, 1, 0);
    a += __atomic_or_fetch(&plain, 1, 0);
    a += __atomic_xor_fetch(&plain, 1, 0);
    a += __atomic_nand_fetch(&plain, 1, 0);
    a += __atomic_min_fetch(&plain, 1, 0);
    a += __atomic_max_fetch(&plain, 1, 0);
    a += __atomic_fetch_add(&byte, 200, 0);
    a += __atomic_compare_exchange_n(&plain, expected, 8, 0, 5, 1);
    a += __atomic_compare_exchange(&plain, expected, desired, 1, 3, 0);
    __atomic_fetch_add(&raw, 4, 5);
    __atomic_sub_fetch(&raw, 4, 5);
    a += __atomic_test_and_set(&flag, 2);
    __atomic_clear(&flag, 3);
    __atomic_thread_fence(5);
    __atomic_signal_fence(0);
    a += __atomic_load_n(&device, 2);
    __atomic_store_n(&plain, a, order + 0);
    return a;
}

